def _ascii_safe(text: str) -> str:
    """Replace non-ASCII characters with ASCII equivalents for safe terminal output."""
    replacements = {
        "\u2014": "--",   # em dash
        "\u2013": "-",    # en dash
        "\u2261": "==",   # triple bar (identical to)
        "\u2192": "->",   # right arrow
        "\u2190": "<-",   # left arrow
        "\u2022": "*",    # bullet
        "\u2500": "-",    # box drawing light horizontal
        "\u2502": "|",    # box drawing light vertical
    }
    for char, replacement in replacements.items():
        text = text.replace(char, replacement)
    # Fallback: encode to ASCII, replacing remaining unknowns
    return text.encode("ascii", errors="replace").decode("ascii")


